-- Every matcher once passing and once failing, as compiled TypeScript calls
-- them (dot calls: the runner is @noSelf).
local runner = require("lua_modules.reforged-test.lua.index")
local describe, it, expect = runner.describe, runner.it, runner.expect

describe("pass", function()
  it("toEqual", function()
    expect(3).toEqual(3)
    expect("a").toEqual("a")
    expect({ 1, { x = 2 } }).toEqual({ 1, { x = 2 } })
  end)
  it("toBe", function()
    local t = {}
    expect(t).toBe(t)
  end)
  it("toBeTruthy", function()
    expect(0).toBeTruthy()
    expect("").toBeTruthy()
  end)
  it("toBeFalsy", function()
    expect(false).toBeFalsy()
    expect(nil).toBeFalsy()
  end)
  it("toBeUndefined", function()
    expect(nil).toBeUndefined()
  end)
  it("toThrow", function()
    expect(function() error("bad thing") end).toThrow()
    expect(function() error("bad thing") end).toThrow("bad thing")
    expect(function() error({ message = "an Error object" }) end).toThrow("Error object")
  end)
  it("toContainCall", function()
    Player(0)
    expect(runner.stubCalls()).toContainCall("Player(0)")
  end)
end)

describe("fail", function()
  it("toEqual on primitives", function()
    expect("a").toEqual("b")
  end)
  it("toEqual on tables", function()
    expect({ a = { 1, 2 } }).toEqual({ a = { 1, 3 } })
  end)
  it("toEqual on a missing key", function()
    expect({}).toEqual({ x = 1 })
  end)
  it("toBe on equal tables", function()
    expect({}).toBe({})
  end)
  it("toBeTruthy", function()
    expect(nil).toBeTruthy()
  end)
  it("toBeFalsy", function()
    expect(0).toBeFalsy()
  end)
  it("toBeUndefined", function()
    expect(Player(0)).toBeUndefined()
  end)
  it("toThrow when nothing is thrown", function()
    expect(function() end).toThrow()
  end)
  it("toThrow with another message", function()
    expect(function() error("bad thing", 0) end).toThrow("good thing")
  end)
  it("toThrow on a non-function", function()
    expect(42).toThrow()
  end)
  it("toContainCall", function()
    Player(1)
    expect(runner.stubCalls()).toContainCall("Player(2)")
  end)
end)
